std::shared_ptr<Node> current = root;
while (infile.read(&bit, 1)) {
    if (bit == '0') {
        if (!current->left) current->left = std::make_shared<Node>();
        current = current->left;
    } else if (bit == '1') {
        if (!current->right) current->right = std::make_shared<Node>();
        current = current->right;
    }
    if (current->symbol != '\0') {
        current = root;
    }
}

